{"CommandLine":"$blPath = "C:\Users\andre\OneDrive\Desktop\xview\FIRMWARE_COMPLETO_B866V2_FASTBOOT\bootloader.img"
$bytes = [System.IO.File]::ReadAllBytes($blPath)
Write-Host "bootloader.img length: $($bytes.Length)"
# Search for gzip header 1F 8B 08 or LZ4 header 04 22 4D 18 or @AML
for ($i = 0; $i -lt $bytes.Length - 4; $i++) {
    if ($bytes[$i] -eq 0x1F -and $bytes[$i+1] -eq 0x8B -and $bytes[$i+2] -eq 0x08) {
        Write-Host "Found GZIP at offset 0x$($i.ToString('X'))"
    }
    if ($bytes[$i] -eq 0x04 -and $bytes[$i+1] -eq 0x22 -and $bytes[$i+2] -eq 0x4D -and $bytes[$i+3] -eq 0x18) {
        Write-Host "Found LZ4 Frame at offset 0x$($i.ToString('X'))"
    }
    if ($bytes[$i] -eq 0x02 -and $bytes[$i+1] -eq 0x21 -and $bytes[$i+2] -eq 0x4C -and $bytes[$i+3] -eq 0x18) {
        Write-Host "Found LZ4 Legacy at offset 0x$($i.ToString('X'))"
    }
}
","WaitMsBeforeAsync":5000,"toolSummary":"Scan bootloader.img for compressed BL33 U-Boot payload"}
